macro_rules! deps {
    () => {
        Result!();
    };
}

macro_rules! extract_archive {
    () => {
        deps!();
        # [doc = " `required_script_identity` is the identity of the script that generated the state that is contained in `archive`."] # [doc = " If this is not the case, the arvhive will be ignored."] fn extract_archive (archive : & Path , destination_dir : & Path , required_script_identity : u32 ,) -> std :: io :: Result < (u32 , Option < String >) > { let archive_buf : Vec < u8 > = { let mut buf = Vec :: new () ; # [cfg_attr (feature = "xz" , allow (unused_mut))] let mut input_archive = std :: fs :: File :: open (archive) ? ; if env :: var_os ("GIX_TEST_IGNORE_ARCHIVES") . is_some () { return Err (std :: io :: Error :: other (format ! ("Ignoring archive at '{}' as GIX_TEST_IGNORE_ARCHIVES is set." , archive . display ()))) ; } # [cfg (feature = "xz")] { let mut decoder = xz2 :: bufread :: XzDecoder :: new (std :: io :: BufReader :: new (input_archive)) ; std :: io :: copy (& mut decoder , & mut buf) ? ; } # [cfg (not (feature = "xz"))] { input_archive . read_to_end (& mut buf) ? ; } buf } ; let mut entry_buf = Vec :: < u8 > :: new () ; let (archive_identity , platform) : (u32 , _) = tar :: Archive :: new (std :: io :: Cursor :: new (& mut & * archive_buf)) . entries_with_seek () ? . filter_map (std :: result :: Result :: ok) . find_map (| mut e : tar :: Entry < '_ , _ > | { let path = e . path () . ok () ? ; if path . parent () ? . file_name () ? == META_DIR_NAME && path . file_name () ? == META_IDENTITY { entry_buf . clear () ; e . read_to_end (& mut entry_buf) . ok () ? ; let mut tokens = entry_buf . to_str () . ok () ? . trim () . splitn (2 , '-') ; match (tokens . next () , tokens . next ()) { (Some (id) , platform) => Some ((id . parse () . ok () ? , platform . map (ToOwned :: to_owned))) , _ => None , } } else { None } }) . ok_or_else (| | std :: io :: Error :: other ("BUG: Could not find meta directory in our own archive")) . map_err (| err | { std :: io :: Error :: other (format ! ("Could not extract archive at '{archive}': {err}" , archive = archive . display ())) }) ? ; if archive_identity != required_script_identity { eprintln ! ("Ignoring archive at '{}' as its generating script changed" , archive . display ()) ; return Err (std :: io :: ErrorKind :: NotFound . into ()) ; } for entry in tar :: Archive :: new (& mut & * archive_buf) . entries () ? { let mut entry = entry ? ; let path = entry . path () ? ; if path . to_str () == Some (META_DIR_NAME) || path . parent () . and_then (Path :: to_str) == Some (META_DIR_NAME) { continue ; } entry . unpack_in (destination_dir) ? ; } Ok ((archive_identity , platform)) }
    };
}

extract_archive!();